using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt(Name = "summarize"), Description("Summarizes the provided text concisely.")]
    public static GetPromptResult Summarize(
        [Description("The text content to summarize.")] string content,
        [Description("Optional desired length: short, medium, or long.")] string length = "medium")
    {
        var instruction = length switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "long" => "Provide a detailed summary of the following text, preserving key points.",
            _ => "Summarize the following text in a concise paragraph."
        };

        return new GetPromptResult
        {
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new TextContentBlock { Text = $"{instruction}\n\n{content}" }
                }
            ]
        };
    }
}

